class FailurePredictor:
    def __init__(self, hidden_units):
        self.layer1 = Dense(hidden_units, activation='relu')
        self.output = Dense(1, activation='sigmoid')

    def forward(self, readings):
        h = self.layer1(readings)
        return self.output(h)

model = FailurePredictor(hidden_units=16)
model.train(all_readings, all_labels, epochs=400)
print(model.evaluate(all_readings, all_labels))

def students_with_absences(students, absences):
    result = []
    for student in students:
        count = 0
        for record in absences:
            if record['student_id'] == student['id']:
                count = count + 1
        if count > 0:
            result.append((student['name'], count))
    for i in range(len(result)):
        for j in range(len(result) - 1):
            if result[j][1] < result[j + 1][1]:
                result[j], result[j + 1] = result[j + 1], result[j]
    return result
